from __future__ import annotations

import re
from typing import Any

from evo2.backends.linear_programming_backend import LinearProgrammingBackend
from evo2.skills.base import Skill, SkillContext, SkillResult


class LinearProgrammingSolverSkill(Skill):
    """Agent-controllable LP/MILP solver skill.

    The skill consumes a domain-neutral linear_program_spec generated by the
    agent/artifact layer. It is useful for exact small instances, relaxations,
    bounds, and linearly representable update stages.
    """

    skill_id = "linear_program_solver_v1"
    skill_type = "solver"
    description = "Solve an explicit public linear_program_spec generated by the artifact layer with an LP/MILP backend."
    suitable_change_scale = "exact or linearly representable"
    handles = ["exact small instances", "linear constraints", "MILP formulations", "bounds and relaxations"]
    limitations = ["requires a valid public linear_program_spec", "not suitable for nonlinear black-box objectives without reformulation"]
    planner_tags = ["linear_program", "lp", "milp", "exact_solver"]

    def __init__(self, backend: LinearProgrammingBackend | None = None):
        self.backend = backend or LinearProgrammingBackend()

    def applicable(self, context: SkillContext) -> bool:
        return bool(self._spec(context))

    def run(self, context: SkillContext) -> SkillResult:
        spec = self._spec(context)
        if not spec:
            return SkillResult(False, None, {"error": "missing linear_program_spec"})
        result = self.backend.solve(spec, time_limit=context.budget.get("solver_time_limit"))
        return SkillResult(
            success=result.success,
            output=result.variable_values,
            metadata={
                "solver": self.skill_id,
                "status": result.status,
                "objective_value": result.objective_value,
                "lower_bound": result.lower_bound,
                "upper_bound": result.upper_bound,
                "gap": result.gap,
                "message": result.message,
                "backend": result.metadata,
            },
        )

    @staticmethod
    def _spec(context: SkillContext) -> dict[str, Any] | None:
        memory_spec = context.memory.get("linear_program_spec") if isinstance(context.memory, dict) else None
        budget_spec = context.budget.get("linear_program_spec") if isinstance(context.budget, dict) else None
        ir_spec = getattr(context.ir, "metadata", {}).get("linear_program_spec") if getattr(context, "ir", None) is not None else None
        return memory_spec or budget_spec or ir_spec


def solution_from_linear_program_spec(spec: dict[str, Any], values: dict[str, float]) -> dict[str, Any]:
    extraction = spec.get("solution_extraction") if isinstance(spec.get("solution_extraction"), dict) else {}
    typ = str(extraction.get("type") or "")
    if not typ and isinstance(extraction.get("selected_variables"), dict):
        typ = "selected_variables"
    if typ in {"solver_values", "raw_solver_values"}:
        return {"solver_values": values}
    if typ == "selected_variables":
        return _selected_variables_solution(extraction, values)
    if typ in {"binary_selection", "selected_items", "selected_item_ids"}:
        variables = extraction.get("variables", []) if isinstance(extraction.get("variables"), list) else []
        if variables and all(isinstance(item, str) for item in variables):
            variables = [{"var": str(name), "id": _selected_variable_id(str(name), re.match(r".*", str(name)), {}, {})} for name in variables]
        if not variables and isinstance(extraction.get("variable_names"), list):
            variables = [{"var": name, "id": _selected_variable_id(str(name), re.match(r".*", str(name)), {}, {})} for name in extraction["variable_names"]]
        if not variables:
            variables = [
                {"var": item.get("name"), "id": item.get("id", _selected_variable_id(str(item.get("name")), re.match(r".*", str(item.get("name"))), {}, {}))}
                for item in spec.get("variables", [])
                if isinstance(item, dict) and str(item.get("type", "")).lower() in {"binary", "bool"}
            ]
        selected = _unique_ids(item["id"] for item in variables if isinstance(item, dict) and _value(values, item.get("var")) >= 0.5)
        field = str(extraction.get("selected_field") or "selected_items")
        solution = {
            "genome": [1 if isinstance(item, dict) and _value(values, item.get("var")) >= 0.5 else 0 for item in variables],
            field: selected,
            "solver_values": values,
        }
        if field != "selected_items":
            solution["selected_items"] = selected
        if extraction.get("also_selected_sets"):
            solution["selected_sets"] = selected
        return solution
    if typ == "open_resource_assignment":
        open_variables = extraction.get("open_variables", []) if isinstance(extraction.get("open_variables"), list) else []
        assignment_variables = extraction.get("assignment_variables", []) if isinstance(extraction.get("assignment_variables"), list) else []
        if not open_variables:
            open_variables = _prefix_open_variables(spec, extraction)
        if not assignment_variables:
            assignment_variables = _prefix_assignment_variables(spec, extraction)
        open_items = [str(item["id"]) for item in open_variables if isinstance(item, dict) and _value(values, item.get("var")) >= 0.5]
        assignments: dict[str, str] = {}
        for item in assignment_variables:
            if isinstance(item, dict) and _value(values, item.get("var")) >= 0.5:
                assignments[str(item.get("customer"))] = str(item.get("facility"))
        open_field = str(extraction.get("open_field") or "open_facilities")
        assignments_field = str(extraction.get("assignments_field") or "assignments")
        solution = {
            "genome": [1 if isinstance(item, dict) and str(item.get("id")) in set(open_items) else 0 for item in open_variables],
            open_field: open_items,
            assignments_field: assignments,
            "solver_values": values,
        }
        solution.setdefault("open_facilities", open_items)
        solution.setdefault("assignments", assignments)
        return solution
    if typ == "precedence_schedule":
        assignments: dict[str, dict[str, Any]] = {}
        operations = extraction.get("operations", []) if isinstance(extraction.get("operations"), list) else []
        for op in operations:
            if not isinstance(op, dict):
                continue
            op_id = str(op.get("id"))
            start = _value(values, op.get("start_var"))
            chosen = None
            best = -1.0
            for item in op.get("machine_vars", []) if isinstance(op.get("machine_vars"), list) else []:
                if not isinstance(item, dict):
                    continue
                score = _value(values, item.get("var"))
                if score > best:
                    best = score
                    chosen = str(item.get("machine"))
            if chosen is None:
                continue
            duration = float(op.get("processing_time", 0.0) or 0.0)
            assignments[op_id] = {"machine": chosen, "start": round(start, 6), "end": round(start + duration, 6)}
        schedule = [
            {"operation_id": op_id, "machine_id": item["machine"], "start_time": item["start"], "end_time": item["end"]}
            for op_id, item in sorted(assignments.items(), key=lambda pair: (pair[1]["start"], pair[0]))
        ]
        genome = [op_id for op_id, _ in sorted(assignments.items(), key=lambda pair: (pair[1]["start"], pair[0]))]
        solution = {
            "genome": genome,
            str(extraction.get("assignments_field") or "assignments"): assignments,
            str(extraction.get("schedule_field") or "schedule"): schedule,
            str(extraction.get("unscheduled_field") or "unscheduled"): [],
            "solver_values": values,
        }
        solution.setdefault("assignments", assignments)
        solution.setdefault("schedule", schedule)
        return solution
    if typ == "generic_assignment":
        assignments: dict[str, Any] = {}
        selected = []
        variable_map = extraction.get("assignment_from_variables")
        if isinstance(variable_map, dict):
            for var, mapped in variable_map.items():
                if _value(values, var) < _num(extraction.get("value_threshold"), 0.5):
                    continue
                decision, resource = _assignment_pair_from_mapping(mapped)
                if decision is None or resource is None:
                    continue
                assignments[str(decision)] = resource
                selected.append(str(decision))
        for item in extraction.get("assignment_variables", []) if isinstance(extraction.get("assignment_variables"), list) else []:
            if isinstance(item, dict) and _value(values, item.get("var")) >= 0.5:
                decision = str(item.get("decision"))
                assignments[decision] = str(item.get("resource"))
                selected.append(decision)
        selected = _unique_ids(selected)
        assignments_field = str(extraction.get("assignments_field") or "assignments")
        selected_field = str(extraction.get("selected_field") or "selected_decisions")
        unassigned_field = str(extraction.get("unassigned_field") or "unassigned")
        solution = {
            assignments_field: assignments,
            selected_field: selected,
            unassigned_field: [],
            "solver_values": values,
        }
        solution.setdefault("assignments", assignments)
        solution.setdefault("selected_decisions", selected)
        solution.setdefault("unassigned", [])
        return solution
    raise ValueError(f"unsupported or missing linear_program_spec.solution_extraction.type: {typ!r}")


def _prefix_open_variables(spec: dict[str, Any], extraction: dict[str, Any]) -> list[dict[str, str]]:
    prefix = str(extraction.get("open_var_prefix") or extraction.get("open_prefix") or "open_")
    variables = []
    for item in spec.get("variables", []) if isinstance(spec.get("variables"), list) else []:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name") or "")
        if not name.startswith(prefix):
            continue
        variables.append({"var": name, "id": name[len(prefix) :]})
    return variables


def _prefix_assignment_variables(spec: dict[str, Any], extraction: dict[str, Any]) -> list[dict[str, str]]:
    configured_prefix = extraction.get("assign_var_prefix") or extraction.get("assignment_var_prefix")
    prefixes = [str(configured_prefix)] if configured_prefix else ["assign_", "x_"]
    resources = [str(item) for item in extraction.get("resources", [])] if isinstance(extraction.get("resources"), list) else []
    resources = sorted(resources, key=len, reverse=True)
    variables = []
    for prefix in prefixes:
        for item in spec.get("variables", []) if isinstance(spec.get("variables"), list) else []:
            if not isinstance(item, dict):
                continue
            name = str(item.get("name") or "")
            if not name.startswith(prefix):
                continue
            tail = name[len(prefix) :]
            customer = None
            facility = None
            for resource in resources:
                suffix = "_" + resource
                if tail.endswith(suffix):
                    customer = tail[: -len(suffix)]
                    facility = resource
                    break
            if customer is None or facility is None:
                parts = tail.rsplit("_", 1)
                if len(parts) != 2:
                    continue
                customer, facility = parts[0], parts[1]
            variables.append({"var": name, "customer": customer, "facility": facility})
        if variables:
            break
    return variables


def _assignment_pair_from_mapping(mapped: Any) -> tuple[Any | None, Any | None]:
    if isinstance(mapped, dict):
        decision = mapped.get("decision") or mapped.get("demand") or mapped.get("item") or mapped.get("task")
        resource = mapped.get("resource") or mapped.get("option") or mapped.get("assignment")
        if resource is None and ("room" in mapped or "slot" in mapped):
            room = mapped.get("room") or mapped.get("room_id")
            slot = mapped.get("slot") or mapped.get("slot_id") or mapped.get("time")
            if room is not None and slot is not None:
                resource = {"room": str(room), "slot": str(slot)}
        if isinstance(resource, dict):
            return decision, resource
        return decision, None if resource is None else str(resource)
    if isinstance(mapped, (list, tuple)):
        if len(mapped) >= 3:
            return mapped[0], f"{mapped[1]}|{mapped[2]}"
        if len(mapped) >= 2:
            return mapped[0], str(mapped[1])
    return None, None


def _selected_variables_solution(extraction: dict[str, Any], values: dict[str, float]) -> dict[str, Any]:
    selected_cfg = extraction.get("selected_variables") if isinstance(extraction.get("selected_variables"), dict) else extraction
    threshold = _num(selected_cfg.get("value_threshold"), 0.5)
    pattern = str(selected_cfg.get("pattern") or ".*")
    regex = re.compile(pattern)
    id_map = extraction.get("id_map") if isinstance(extraction.get("id_map"), dict) else {}
    variables = extraction.get("variables") if isinstance(extraction.get("variables"), list) else []
    variable_ids = {
        str(item.get("var")): str(item.get("id"))
        for item in variables
        if isinstance(item, dict) and item.get("var") not in (None, "") and item.get("id") not in (None, "")
    }
    selected = []
    for var in values:
        if _value(values, var) < threshold:
            continue
        match = regex.match(str(var))
        if not match:
            continue
        selected.append(_selected_variable_id(str(var), match, id_map, variable_ids))
    selected = _unique_ids(selected)
    field = str(extraction.get("output_field") or extraction.get("selected_field") or "selected_items")
    solution = {field: selected, "solver_values": values}
    if field != "selected_items":
        solution["selected_items"] = selected
    return solution


def _selected_variable_id(var: str, match: re.Match[str], id_map: dict[str, Any], variable_ids: dict[str, str]) -> str:
    if var in variable_ids:
        return variable_ids[var]
    if var in id_map:
        return str(id_map[var])
    if match.groups():
        return str(next((group for group in match.groups() if group not in (None, "")), var))
    for prefix in ("x__", "x_", "select__", "select_", "open__", "open_", "use__", "use_"):
        if var.startswith(prefix):
            return var[len(prefix) :]
    return var


def _unique_ids(values: Any) -> list[str]:
    output: list[str] = []
    seen: set[str] = set()
    for value in values:
        item = str(value)
        if item in seen:
            continue
        seen.add(item)
        output.append(item)
    return output


def _num(value: Any, default: float = 0.0) -> float:
    try:
        if value in (None, ""):
            return float(default)
        return float(value)
    except Exception:
        return float(default)


def _value(values: dict[str, float], name: Any) -> float:
    try:
        return float(values.get(str(name), 0.0))
    except Exception:
        return 0.0
